from pathlib import Path
import base64,hashlib,json,subprocess,sys,zipfile
W=Path('/kaggle/working/hp_round14');R=Path('/root/r14_code_v1')
assert not R.exists();R.mkdir()
p=W/'sources_v1.zip.dat';assert hashlib.sha256(p.read_bytes()).hexdigest()=='16611a4257f2a6a9be32fc2ebe85c848d03710f81cda9753bfc35522cf5c7dd6'
with zipfile.ZipFile(p) as z:
    for r in json.loads(z.read('source_manifest.json')):
        p=(R/r['path']).resolve();assert p.is_relative_to(R)
        raw=z.read(r['path']);assert len(raw)==r['bytes'] and hashlib.sha256(raw).hexdigest()==r['sha256']
        p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(raw)
Path('/root/r14_dispatch_worker.py').write_bytes(base64.b64decode(''))
pids={}
for name,path in [('dispatch','/root/r14_dispatch_worker.py'),('full_verify',str(R/'research_round14_full_verify_worker.py'))]:
    p=subprocess.Popen(['python',path],stdin=subprocess.DEVNULL,stdout=(W/(name+'.log')).open('ab'),stderr=subprocess.STDOUT,start_new_session=True)
    pids[name]=p.pid
print(json.dumps(pids))